import { i18n } from 'src/boot/i18n';
import { objLen } from 'src/utils/general';
import { LOW_CONFIDENCE } from 'src/constants';
import type { dynamicObj } from 'src/pages/assets';
import { textValidator } from 'src/validatior/index';
import displayFieldLabel from 'src/utils/displayFieldLabel';
import { notify } from 'src/components/notifications/notify';
import voucherTextField from 'src/assets/voucher-text.json';

/**
 * The local (client side) field validation that runs before a document is
 * exported, saved-and-validated, or handed to another screen.
 *
 * It used to be copy-pasted as `validateExportData` and its helpers into every
 * screen that owns a form-builder model (ValidationScreen, COA, MediOrder), and
 * the copies had drifted, so the same document validated differently depending
 * on which button was pressed. This is the one implementation.
 *
 * The models are passed in rather than read off `this`, because the document
 * store calls this too (see `validateFields`) and has no component.
 */

// Field labels come from the displayFieldLabel mixin, whose methods lean on
// `this`. Binding them to a bare object gives the same resolution order
// without a component instance.
const labelResolver = { ...displayFieldLabel.methods } as dynamicObj;

export function setFieldInputError(
  formBuilderModel: dynamicObj,
  field_name: string,
  error_message: string,
) {
  formBuilderModel[field_name].input_error = error_message;
}

/**
 * A field that has since been filled must not keep the REQUIRED code the
 * backend stamped on it, or it fails on a value that is now there.
 */
export function updateFieldErrors(
  formBuilderModel: dynamicObj,
  formBuilderConfigModel: dynamicObj,
) {
  for (const [field_name, fieldDef] of Object.entries(formBuilderModel) as [
    string,
    dynamicObj,
  ][]) {
    if (
      formBuilderConfigModel[field_name].is_required &&
      fieldDef.formatted_value &&
      fieldDef.validation_code === 'REQUIRED'
    ) {
      fieldDef.validation_code = '';
    }
  }
}

export function setFieldErrors(
  formBuilderModel: dynamicObj,
  formBuilderConfigModel: dynamicObj,
  skipLowConfidance: boolean,
) {
  let fields_has_errors = false;

  for (const [field_name, fieldDef] of Object.entries(formBuilderModel) as [
    string,
    dynamicObj,
  ][]) {
    setFieldInputError(formBuilderModel, field_name, '');

    if (formBuilderConfigModel[field_name].is_required && !fieldDef.formatted_value) {
      fields_has_errors = true;

      // Neither a hidden field nor one missing from the layout can show an
      // inline error, so the user is told out of band.
      if (formBuilderConfigModel[field_name].is_hidden) {
        notify.error(field_name + ' : ' + i18n.t('field_required_but_hidden'));
        continue;
      }

      if (formBuilderConfigModel[field_name].not_in_layout) {
        notify.error(field_name + ' : ' + i18n.t('field_required_but_not_in_layout'));
        continue;
      }

      setFieldInputError(formBuilderModel, field_name, i18n.t('field_required'));
      continue;
    }

    // Deliberately does not set fields_has_errors: a mismatch is shown to the
    // user but has never blocked the flow.
    if (
      fieldDef.validation_code &&
      fieldDef.validation_code === 'AMOUNTS_MISMATCH'
    ) {
      setFieldInputError(
        formBuilderModel,
        field_name,
        fieldDef.validation_message,
      );
    }

    if (fieldDef.is_valid) {
      continue;
    }

    if (
      !fieldDef.validation_code ||
      (skipLowConfidance && LOW_CONFIDENCE.includes(fieldDef.validation_code))
    ) {
      continue;
    }

    let error_message = formBuilderModel[field_name].validation_message;
    if (!error_message) {
      error_message = i18n.t(fieldDef.validation_code);
    }

    fields_has_errors = true;
    setFieldInputError(formBuilderModel, field_name, error_message);
  }

  return fields_has_errors;
}

export async function checkValidationError(
  formBuilderModel: dynamicObj,
  formBuilderConfigModel: dynamicObj,
) {
  let fields_has_validation_errors = false;

  for (const [field_name, fieldDef] of Object.entries(formBuilderModel) as [
    string,
    dynamicObj,
  ][]) {
    if (formBuilderConfigModel[field_name].fieldType !== 'TextInput') {
      continue;
    }

    const field_value = fieldDef.formatted_value;
    if (!field_value || field_value == '') {
      continue;
    }

    const fieldConfigModel = formBuilderConfigModel[field_name];
    let is_valid = true;
    let input_error = '';

    ({ is_valid, input_error } = await textValidator.init(
      fieldDef,
      fieldConfigModel,
    ));

    if (is_valid) {
      continue;
    }

    formBuilderModel[field_name].formatted_value = '';
    setFieldInputError(formBuilderModel, field_name, input_error);
    fields_has_validation_errors = true;
  }

  return fields_has_validation_errors;
}

function getRequiredFieldsErrorMessage(
  formBuilderConfigModel: dynamicObj,
  field_list: string[],
) {
  const fields_with_labels = [];
  for (const field_name of field_list) {
    fields_with_labels.push(
      labelResolver.getFieldLabel(formBuilderConfigModel[field_name], ''),
    );
  }

  let error_message = i18n.t('atleast_fill_one_field');
  error_message = error_message.replace('#', fields_with_labels.join(', '));
  return error_message;
}

/** Returns true when every "at least one of these" group has a value. */
export function validateRequiredFieldRules(
  record: dynamicObj,
  formBuilderModel: dynamicObj,
  formBuilderConfigModel: dynamicObj,
) {
  let is_validate = true;

  if (
    !record.hasOwnProperty('required_field_pairs') ||
    !Array.isArray(record.required_field_pairs) ||
    record.required_field_pairs.length == 0
  ) {
    return is_validate;
  }

  Array.from(record.required_field_pairs).forEach((fields_list: any) => {
    let has_value = false;
    for (const field_name of fields_list) {
      if (formBuilderModel[field_name].formatted_value) {
        has_value = true; // if atleast one of the field has value
      }
    }

    if (has_value) {
      return;
    }

    is_validate = false;
    const error_message = getRequiredFieldsErrorMessage(
      formBuilderConfigModel,
      fields_list,
    );

    for (const field_name of fields_list) {
      setFieldInputError(formBuilderModel, field_name, error_message);
    }
  });

  return is_validate;
}

/**
 * True when a save-and-validate failure is entirely line-item rows.
 *
 * The backend answers every validation failure with "One or more fields need
 * validation", even one where `fields_valid` is true and everything sits under
 * `errors.tables`. It reports the two separately, so the wording can follow:
 *
 *   errors: { fields: {}, tables: { INVOICE_TABLE: [ { message, col_name,
 *            row_index, message_code }, ... ] } }
 *
 * A field error always wins — a document with both is still, first, a document
 * with a field to fix.
 */
export function isTableOnlyValidationError(errors: dynamicObj | undefined) {
  if (!errors) {
    return false;
  }

  const field_errors = errors.fields ? objLen(errors.fields) : 0;
  if (field_errors > 0) {
    return false;
  }

  return Object.values(errors.tables || {}).some(
    (table_errors: any) => Array.isArray(table_errors) && table_errors.length > 0,
  );
}

export function findFirstErrorField(formBuilderModel: dynamicObj) {
  for (const [field_name, fieldDef] of Object.entries(formBuilderModel) as [
    string,
    dynamicObj,
  ][]) {
    if (fieldDef.input_error) {
      return field_name;
    }
  }
  return '';
}

/**
 * The whole local pass: required fields, per-field validation codes, the text
 * validator, and the "at least one of" rules. Returns true when the document
 * has errors. Scrolling and focusing stay with the caller — the store has no
 * DOM.
 */
export async function validateDocumentFields(
  record: dynamicObj,
  formBuilderModel: dynamicObj,
  formBuilderConfigModel: dynamicObj,
) {
  updateFieldErrors(formBuilderModel, formBuilderConfigModel);

  const fields_has_errors = setFieldErrors(
    formBuilderModel,
    formBuilderConfigModel,
    true,
  );
  const validation_errors = await checkValidationError(
    formBuilderModel,
    formBuilderConfigModel,
  );
  const required_fields_errors = !validateRequiredFieldRules(
    record,
    formBuilderModel,
    formBuilderConfigModel,
  );

  return fields_has_errors || validation_errors || required_fields_errors;
}

/**
 * Max length configured for the voucher-text field, used by the M3
 * auto-accounting inputs to drive `:maxlength` and `:counter`.
 *
 * NOTE: `field_name` is not read — the lookup always resolves the voucher_text
 * definition, which is the only field the asset describes. Every call site
 * passes 'voucher_text', so the parameter is kept to leave them untouched.
 *
 * Returns undefined when the definition carries no max_length rule; both
 * bindings read that as "no limit, no counter".
 */
export function getFieldLength(field_name: string): number | undefined {
  const fieldsConfig = voucherTextField['voucher_text'];

  if (!fieldsConfig || !fieldsConfig.validation_rules) {
    return undefined;
  }

  const maxLengthRule = fieldsConfig.validation_rules.find(
    (rule: any) => rule.rule === 'max_length',
  );

  if (!maxLengthRule) {
    return undefined;
  }

  return maxLengthRule.value;
}
